const byte RED_PIN = 11;
const byte YELLOW_PIN = 10;
const byte GREEN_PIN = 9;
const byte BUTTON_PIN = 2;

const unsigned long DEBOUNCE_MS = 30;
const unsigned long YELLOW_MS = 2000;
const unsigned long WALK_MS = 5000;

enum Phase { TRAFFIC_GREEN, TRAFFIC_YELLOW, WALK_RED };
Phase phase = TRAFFIC_GREEN;
unsigned long phaseStarted = 0;
unsigned long lastChange = 0;
int lastReading = HIGH;
int stableReading = HIGH;

void showPhase() {
  digitalWrite(RED_PIN, phase == WALK_RED ? HIGH : LOW);
  digitalWrite(YELLOW_PIN, phase == TRAFFIC_YELLOW ? HIGH : LOW);
  digitalWrite(GREEN_PIN, phase == TRAFFIC_GREEN ? HIGH : LOW);
}

void setup() {
  pinMode(RED_PIN, OUTPUT);
  pinMode(YELLOW_PIN, OUTPUT);
  pinMode(GREEN_PIN, OUTPUT);
  pinMode(BUTTON_PIN, INPUT_PULLUP);
  showPhase();
}

void loop() {
  unsigned long now = millis();
  int reading = digitalRead(BUTTON_PIN);

  if (reading != lastReading) {
    lastReading = reading;
    lastChange = now;
  }

  if (now - lastChange >= DEBOUNCE_MS && reading != stableReading) {
    stableReading = reading;
    if (stableReading == LOW && phase == TRAFFIC_GREEN) {
      phase = TRAFFIC_YELLOW;
      phaseStarted = now;
      showPhase();
    }
  }

  if (phase == TRAFFIC_YELLOW && now - phaseStarted >= YELLOW_MS) {
    phase = WALK_RED;
    phaseStarted = now;
    showPhase();
  } else if (phase == WALK_RED && now - phaseStarted >= WALK_MS) {
    phase = TRAFFIC_GREEN;
    phaseStarted = now;
    showPhase();
  }
}

